# owner: platform
from typing import Iterable
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed

# ---
def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Absence notice for a parent, oldest day first."""
    all_marks = list(marks)
    stray_ids = {mark.student_id for mark in all_marks}
    stray_ids.discard(student.student_id)
    if stray_ids:
        raise ValueError(
            f"marks for other students: {sorted(stray_ids)}"
        )
    missed = days_missed(all_marks)
    if not missed:
        raise ValueError(
            f"no absences for {student.student_id}"
        )
    dates = ", ".join(
        missed_day.isoformat() for missed_day in missed
    )
    name = f"{student.first_name} {student.last_name}"
    count = len(missed)
    noun = "day" if count == 1 else "days"
    return (
        "Dear parent or guardian,\n\n"
        f"{name} was absent {count} {noun}: {dates}.\n"
    )
